inline Key sample(int type,float phase,bool striking=false){float f=std::clamp(phase,0.f,1.f)*60;int i=std::min(59,int(f));float t=f-i;auto a=(striking?attack:walk)[type][i],b=(striking?attack:walk)[type][i+1];return {a.travel+(b.travel-a.travel)*t,a.lift+(b.lift-a.lift)*t,a.bob+(b.bob-a.bob)*t,a.sway+(b.sway-a.sway)*t};}
